import math

def preference_margin(r_chosen: float, r_rejected: float) -> float:
    return round(r_chosen - r_rejected, 4)

def preference_probability(r_chosen: float, r_rejected: float) -> float:
    """Sigmoid of the margin -- probability chosen beats rejected."""
    margin = preference_margin(r_chosen, r_rejected)
    return round(1 / (1 + math.exp(-margin)), 4)

print(preference_probability(0.27, -0.27))
